@import url("https://python.catppuccin.com/pygments/catppuccin-variables.important.css");
@media (prefers-color-scheme: light) {
  :root {
    color-scheme: light;
    --ctp-rosewater: #dc8a78;
    --ctp-flamingo: #dd7878;
    --ctp-pink: #ea76cb;
    --ctp-mauve: #8839ef;
    --ctp-red: #d20f39;
    --ctp-maroon: #e64553;
    --ctp-peach: #fe640b;
    --ctp-yellow: #df8e1d;
    --ctp-green: #40a02b;
    --ctp-teal: #179299;
    --ctp-sky: #04a5e5;
    --ctp-sapphire: #209fb5;
    --ctp-blue: #1e66f5;
    --ctp-lavender: #7287fd;
    --ctp-text: #4c4f69;
    --ctp-subtext1: #5c5f77;
    --ctp-subtext0: #6c6f85;
    --ctp-overlay2: #7c7f93;
    --ctp-overlay1: #8c8fa1;
    --ctp-overlay0: #9ca0b0;
    --ctp-surface2: #acb0be;
    --ctp-surface1: #bcc0cc;
    --ctp-surface0: #ccd0da;
    --ctp-base: #eff1f5;
    --ctp-mantle: #e6e9ef;
    --ctp-crust: #dce0e8;
  }
  :root ::selection {
    background-color: rgba(136, 57, 239, 0.3);
  }
  :root input::placeholder,
  :root textarea::placeholder {
    color: #6c6f85 !important;
  }
  :root ::selection {
    color: unset;
  }
  :root body {
    background-color: #eff1f5 !important;
    color: #4c4f69 !important;
  }
  :root input,
  :root select,
  :root textarea {
    background-color: #e6e9ef !important;
    border-color: #ccd0da !important;
    color: #4c4f69 !important;
  }
  :root input:active,
  :root select:active,
  :root textarea:active,
  :root input:focus,
  :root select:focus,
  :root textarea:focus,
  :root input:hover,
  :root select:hover,
  :root textarea:hover {
    border-color: #8839ef !important;
    box-shadow: inset 0 0 0 1px #8839ef !important;
  }
  :root input:disabled,
  :root select:disabled,
  :root input:disabled:active,
  :root select:disabled:active,
  :root input:disabled:focus,
  :root select:disabled:focus,
  :root input:disabled:hover,
  :root select:disabled:hover {
    background-color: #e6e9ef !important;
  }
  :root hr {
    background-color: #ccd0da !important;
    background-image: linear-gradient(90deg, #ccd0da, #ccd0da) !important;
  }
  :root .project-description blockquote {
    color: #6c6f85 !important;
  }
  :root .project-description table tr {
    background-color: #eff1f5 !important;
  }
  :root .project-description table tr:nth-child(odd) {
    background-color: #e6e9ef !important;
  }
  :root .project-description table,
  :root .project-description table tr,
  :root .project-description table th,
  :root .project-description table td {
    border-color: #ccd0da !important;
  }
  :root .verified .check {
    color: #40a02b;
  }
  :root .banner,
  :root .footer {
    background-color: #e6e9ef !important;
    color: #4c4f69 !important;
  }
  :root .accordion__link {
    color: #8839ef !important;
  }
  :root .password-strength {
    border-color: #acb0be !important;
  }
  :root .accordion__link:active,
  :root .accordion__link:focus {
    outline-color: #8839ef !important;
    outline-style: solid;
  }
  :root .footer__divider {
    border-color: #ccd0da !important;
  }
  :root a:active,
  :root .footer__menu li a:active,
  :root a:focus,
  :root .footer__menu li a:focus {
    outline-color: #8839ef !important;
  }
  :root .skip-to-content:focus {
    background-color: #eff1f5 !important;
    color: #4c4f69 !important;
  }
  :root a:not(.site-header__logo, .button, .dropdown__link, .badge, .release__card),
  :root a:hover:not(
      .site-header__logo,
      .button,
      .dropdown__link,
      .badge,
      .release__card
    ),
  :root .footer__menu li a,
  :root .footer__text a,
  :root .language-switcher ul button {
    color: #8839ef !important;
  }
  :root .footer__text a:active,
  :root .language-switcher ul button:active,
  :root .footer__text a:focus,
  :root .language-switcher ul button:focus {
    outline-color: #8839ef !important;
  }
  :root .footer__menu h2,
  :root .footer__text,
  :root .language-switcher ul button.language-switcher__selected::before {
    color: #4c4f69 !important;
  }
  :root .language-switcher {
    background-color: #dce0e8 !important;
    border-top-color: #dce0e8 !important;
    color: #4c4f69 !important;
